<script setup lang="ts">
import DeskSelect from '@/presentation/shared/DeskSelect.vue';
import { useUiLocale } from '@/application/shared/UseUiLocale';
import {computed,onScopeDispose,ref,watch} from 'vue';
import { useErrorToast } from '@/application/shared/UseFeedback';
import ContentSkeleton from '@/presentation/shared/ContentSkeleton.vue';
import { productReviewIssueCount, unconfirmedProductLocales } from '@/domain/workspace/ProductReview';
import ProductEditor from './ProductEditor.vue';
import {Button} from '@wow-two-beta/fe/presentation/actions';
import {failureMessage,type AccessControls} from '@/application/workspace/UseAccess';
import type {WorkspaceControls} from '@/application/workspace/UseWorkspace';
import {useCommerce} from '@/application/workspace/UseCommerce';
import {emptyCopy,initialCommerce,words,type CommerceDraft,type CommerceRelease,type CommerceSnapshot,type Product,type Provenance} from '@/domain/workspace/Commerce';

const { t, uiLocale } = useUiLocale();

defineOptions({name:'CommercePage'});
const props=defineProps<{access:AccessControls;workspace:WorkspaceControls}>();
const api=useCommerce(props.access);
const org=()=>props.workspace.organization.value!.id;
const newKey=()=>crypto.randomUUID();
const confirmedRevision=ref<number|null>(null);
const brandId=ref('');const current=ref<CommerceDraft|null>(null);const snapshot=ref<CommerceSnapshot|null>(null);
const baseline=ref('');const releases=ref<CommerceRelease[]>([]);const message=ref('');const error=ref('');const loading=ref(false);
useErrorToast(error);
const tab=ref('products');const productId=ref('');const newId=ref('');const note=ref('');const libraryId=ref('');const logoSlot=ref('master');
const controller=new AbortController();let loadSequence=0;const dirty=computed(()=>snapshot.value!==null&&JSON.stringify(snapshot.value)!==baseline.value);
const selected=computed(()=>snapshot.value?.products.find(p=>p.document.id===productId.value));
function updateProduct(product: Product): void {
 const index=snapshot.value?.products.findIndex(item=>item.document.id===product.document.id)??-1;
 if(snapshot.value && index>=0)snapshot.value.products[index]=product;
}
const images=computed(()=>Object.entries(snapshot.value?.mediaApprovals??{}));
const blocked=computed(()=>loading.value||props.access.busy.value);
watch(dirty,value=>props.access.setDirty(value),{flush:'sync'});
onScopeDispose(()=>{controller.abort();props.access.setDirty(false);});
watch(()=>props.workspace.brands.value,brands=>{if(!brandId.value&&brands?.length)brandId.value=brands[0]!.id;},{immediate:true});
watch(brandId,()=>void load(),{immediate:true});
async function load(){if(!brandId.value)return;const sequence=++loadSequence;loading.value=true;error.value='';message.value='';const requested=brandId.value;const organization=org();if(current.value&&current.value.brandId!==requested){current.value=null;confirmedRevision.value=null;snapshot.value=null;releases.value=[];}
 try{const [draft,history]=await Promise.all([api.get(organization,requested,controller.signal),api.releases(organization,requested,controller.signal)]);
 if(controller.signal.aborted||sequence!==loadSequence||brandId.value!==requested||org()!==organization)return;
 if(!draft.ok){error.value=failureMessage(draft.failure);return false;}current.value=draft.value;confirmedRevision.value=draft.value?.revision??null;snapshot.value=draft.value?structuredClone(draft.value.snapshot):null;baseline.value=JSON.stringify(snapshot.value);if(history.ok)releases.value=history.value;else error.value=failureMessage(history.failure);if(!snapshot.value?.products.some(item=>item.document.id===productId.value))productId.value=snapshot.value?.products[0]?.document.id??'';return true;
 }finally{if(sequence===loadSequence)loading.value=false;}}
function start(){const brand=props.workspace.brands.value?.find(b=>b.id===brandId.value);if(!brand)return;snapshot.value=initialCommerce(brand.name,brand.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''));}
async function adopt(){error.value='';const brand=props.workspace.brands.value?.find(b=>b.id===brandId.value);const slug=(brand?.name??'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
 const result=await props.access.write(signal=>api.adopt(org(),brandId.value,slug,signal),controller.signal);
 if(result.ok){await load();message.value='Preserved records copied into a private draft. Review image provenance before publication.';}else error.value=failureMessage(result.failure);}
async function save(){if(!snapshot.value)return false;error.value='';const result=await props.access.write(signal=>api.save(org(),brandId.value,confirmedRevision.value??current.value?.revision??0,snapshot.value!,signal),controller.signal);
 if(result.ok){confirmedRevision.value=result.value.revision;const refreshed=await load();if(!refreshed)error.value='Saved successfully. The current view could not refresh. Your local edits are preserved.';if(refreshed)message.value=t('Draft revision {revision} saved.',{revision:result.value.revision});return Boolean(refreshed);}error.value=failureMessage(result.failure);return false;}
function addProduct(){if(!snapshot.value||!newId.value||snapshot.value.products.some(p=>p.document.id===newId.value))return;
 const id=newId.value;const product:Product={revision:1,sourceRevision:null,document:{id,garmentType:'garment',variantCode:id,status:'draft',sortOrder:snapshot.value.products.length,sizes:[],fabricCodes:[],decorationCodes:[],tags:[],locales:{uz:emptyCopy(),ru:emptyCopy(),en:emptyCopy()},pricing:null,media:[],issues:[],notes:null,stock:null,madeToOrder:false}};
 snapshot.value.products.push(product);productId.value=id;newId.value='';}
function addCollection(){if(!snapshot.value)return;const id=`collection-${crypto.randomUUID().slice(0,8)}`;snapshot.value.collections.push({id,names:words(),description:null,productIds:[],isPublished:false,sortOrder:snapshot.value.collections.length});}
function setVerified(key:string,event:Event){if(!snapshot.value)return;const checked=(event.target as HTMLInputElement).checked;snapshot.value.verifiedLinkKeys=snapshot.value.verifiedLinkKeys.filter(k=>k!==key);if(checked)snapshot.value.verifiedLinkKeys.push(key);}
async function attach(asLogo=false){const media=props.workspace.media.value?.find(m=>m.id===libraryId.value);if(!media||!snapshot.value)return;if(dirty.value&&!await save())return;
 const provenance:Provenance={kind:'unknown',approvedForPublication:false,sourceUrl:null,credit:null,rights:null};
 const result=await props.access.write(signal=>api.attach(org(),brandId.value,current.value!.revision,media.id,provenance,signal),controller.signal);
 if(!result.ok){error.value=failureMessage(result.failure);return;}if(!await load())return;
 if(asLogo)snapshot.value!.logos[logoSlot.value]={...media,slot:logoSlot.value,status:'draft',uploadedAt:media.createdAtUtc,width:null,height:null,hasPreview:false,alt:null,sourcePath:null,role:'logo'};
 else if(selected.value&&!selected.value.document.media.some(image=>image.id===media.id))selected.value.document.media.push({id:media.id,role:'photo',fileName:media.fileName,contentType:media.contentType,byteLength:media.byteLength,sha256:media.sha256,width:null,height:null,hasPreview:false,alt:null,sourcePath:null});
 await save();}
async function publish(){if(!current.value||dirty.value)return;error.value='';const result=await props.access.write(signal=>api.publish(org(),brandId.value,current.value!.revision,note.value,signal),controller.signal);
 if(result.ok){if(await load())note.value='';message.value=t('Release {revision} published. Your approved catalogue is available to connected public apps.',{revision:result.value.revision});}else error.value=failureMessage(result.failure);}
async function withdraw(release:CommerceRelease){if(dirty.value||!note.value.trim())return;const result=await props.access.write(signal=>api.withdraw(org(),brandId.value,release.id,note.value,signal),controller.signal);if(result.ok){await load();message.value='Release withdrawn. Pinned public links now return unavailable.';}else error.value=failureMessage(result.failure);}
</script>

<template>
<section class="space-y-6">
 <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="eyebrow">{{ t("Brand authority") }}</p><h1 class="page-title">{{ t("Products & releases") }}</h1><p class="text-muted-foreground">{{ t("Manage your products, identity and the catalogue your customers see.") }}</p></div>
 <div class="flex items-end gap-3"><Button variant="outline" :is-disabled="blocked||dirty||!brandId" :is-loading="loading" @click="load">{{t("Refresh")}}</Button><label>{{ t("Brand") }}<DeskSelect v-model="brandId" class="mt-2" :disabled="dirty||blocked" :label="t('Brand')" :options="[({ value: '' as const, label: (t('Choose a brand')) }), ...(workspace.brands.value ?? []).map(brand => ({ value: brand.id, label: (brand.name) }))]" /></label></div></div>
<p v-if="message" role="status" class="rounded-lg bg-muted p-3 text-sm">{{ t(message) }}</p>
 <p v-if="!brandId" class="empty-state">{{ t("Create a brand in Brands to begin.") }}</p><ContentSkeleton v-if="loading&&!snapshot" variant="form" :label="t('Loading brand records…')" />
 <p v-else-if="error&&!snapshot" class="query-label" role="status">{{ t("Product library unavailable") }}</p>
 <section v-else-if="!snapshot" class="workspace-card space-y-4 p-7"><h2 class="text-xl font-semibold">{{ t("Start this brand’s product library") }}</h2><p>{{ t("Records remain private until an owner publishes a release.") }}</p><div v-if="workspace.canEdit.value" class="flex flex-wrap gap-3"><Button @click="start">{{ t("Start an empty draft") }}</Button><Button v-if="workspace.canApprove.value" variant="outline" :is-disabled="blocked" @click="adopt">{{ t("Adopt preserved Ocharo records") }}</Button></div><p class="text-sm text-muted-foreground">{{ t("Adoption preserves original product IDs, copy, prices, collections and image hashes. Every image starts awaiting publication review.") }}</p></section>
 <div v-if="snapshot" :aria-busy="loading">
  <div class="flex flex-wrap items-center justify-between gap-4 rounded-xl bg-muted p-4"><div><b>{{snapshot.products.length}}</b> {{ t("products ·") }} <b>{{snapshot.collections.length}}</b> {{ t("collections · Draft") }} {{current?.revision??t('unsaved')}} <span v-if="dirty">{{ t("· Unsaved changes") }}</span></div><Button v-if="workspace.canEdit.value" :is-disabled="blocked||!dirty" @click="save">{{ t("Save draft") }}</Button></div>
  <nav :aria-label="t('Brand review')" class="flex flex-wrap gap-2"><Button v-for="item in ['products','identity','collections','images','releases']" :key="item" size="sm" :variant="tab===item?'soft':'ghost'" @click="tab=item">{{t(({products:'Products',identity:'Brand identity',collections:'Collections',images:'Image review',releases:'Publish & history'})[item]??item)}}</Button></nav>
  <fieldset :disabled="blocked||!workspace.canEdit.value" class="min-w-0">
  <div v-if="tab==='products'" class="grid gap-6 lg:grid-cols-[260px_1fr]">
   <aside class="space-y-3"><label class="sr-only" for="new-product">{{ t("New product ID") }}</label><input id="new-product" v-model="newId" class="native-input" :placeholder="t('e.g. nimcha-v08')" pattern="[a-z0-9-]+"/><Button variant="outline" size="sm" :is-disabled="!newId" @click="addProduct">{{ t("Add product") }}</Button>
    <button v-for="item in snapshot.products" :key="item.document.id" class="block w-full rounded-xl border p-4 text-left" :class="productId===item.document.id?'border-primary bg-muted':'border-border'" @click="productId=item.document.id"><b class="block">{{item.document.locales.en.name||item.document.locales.uz.name||item.document.id}}</b><span class="text-xs text-muted-foreground">{{item.document.id}} · {{ t(item.document.status) }}</span><span v-if="productReviewIssueCount(item)" class="mt-2 block text-xs font-medium text-destructive">{{ t('{count} review issues',{count:productReviewIssueCount(item)}) }}</span><span v-if="unconfirmedProductLocales(item).length" class="mt-1 block text-xs text-muted-foreground">{{ t('Unconfirmed') }}: {{unconfirmedProductLocales(item).join(', ')}}</span></button>
   </aside>
   <article v-if="selected" class="workspace-card space-y-5 p-6"><header><h2 class="text-xl font-semibold">{{selected.document.id}}</h2><p class="text-xs text-muted-foreground">{{ t("Stable ID · Product revision") }} {{selected.revision}}<span v-if="selected.sourceRevision"> {{ t("· Imported source revision") }} {{selected.sourceRevision}}</span></p></header>
    <ProductEditor :product="selected" @update:product="updateProduct" :can-approve="workspace.canApprove.value" :image-url="sha=>api.image(org(),brandId,sha)" />
    <div class="flex flex-wrap items-center gap-3"><DeskSelect v-model="libraryId" :label="t('Image from media library')" class="max-w-sm" :disabled="blocked || !workspace.canEdit.value" :options="[({ value: '' as const, label: (t('Choose an uploaded image')) }), ...(workspace.media.value ?? []).map(media => ({ value: media.id, label: (media.fileName) }))]" /><Button size="sm" variant="outline" :is-disabled="!libraryId" @click="attach(false)">{{ t("Attach image") }}</Button></div>
    <label class="block">{{ t("Private notes") }}<textarea v-model="selected.document.notes" rows="2" class="native-input mt-2" /></label>
    <section v-if="selected.document.issues.length" class="space-y-2"><h3 class="font-semibold">{{ t("Product checks") }}</h3><label v-for="issue in selected.document.issues" :key="issue.id" class="flex gap-2"><input type="checkbox" :checked="issue.status==='resolved'" @change="issue.status=($event.target as HTMLInputElement).checked?'resolved':'open'"/>{{issue.question}}</label><p class="text-xs text-muted-foreground">{{ t("These are unresolved product facts, not customer FAQs. Resolve them before publication.") }}</p></section>
   </article><p v-else class="editor-prompt">{{ t("Select a product or add its stable ID.") }}</p>
  </div>
  <div v-else-if="tab==='identity'" class="workspace-card space-y-5 p-6">
   <div class="grid gap-4 sm:grid-cols-2"><label>{{ t("Brand name") }}<input v-model="snapshot.identity.name" class="native-input mt-2" /></label><label>{{ t("Public slug") }}<input v-model="snapshot.slug" :disabled="releases.length>0" class="native-input mt-2"/><span class="text-xs text-muted-foreground">{{ t("Fixed after first publication.") }}</span></label></div>
   <div v-for="language in ['uz','ru','en'] as const" :key="language" class="grid gap-4 sm:grid-cols-2"><label>{{language.toUpperCase()}} {{ t("tagline") }}<input v-model="snapshot.identity.tagline[language]" class="native-input mt-2"/></label><label>{{language.toUpperCase()}} {{ t("description") }}<textarea v-model="snapshot.identity.descriptor[language]" class="native-input mt-2" rows="2"/></label></div>
   <h3 class="font-semibold">{{ t("Palette") }}</h3><div v-for="color in snapshot.identity.palette" :key="color.key" class="flex flex-wrap gap-3"><input v-model="color.hex" type="color" :aria-label="color.name"/><input v-model="color.name" class="native-input max-w-xs" :aria-label="t('Color name')"/><input v-model="color.role" class="native-input max-w-xs" :aria-label="t('Color role')"/></div><Button size="sm" variant="outline" @click="snapshot.identity.palette.push({key:newKey(),name:t('New color'),hex:'#000000',role:'accent'})">{{ t("Add color") }}</Button>
   <h3 class="font-semibold">{{ t("Official destinations") }}</h3><div v-for="link in snapshot.identity.links" :key="link.key" class="space-y-2 rounded-lg border border-border p-4"><div class="grid gap-3 sm:grid-cols-2"><input v-model="link.label" :aria-label="t('Link label')" class="native-input"/><input v-model="link.url" :aria-label="t('HTTPS destination')" type="url" class="native-input"/></div><label v-if="workspace.canApprove.value" class="flex gap-2"><input type="checkbox" :checked="snapshot.verifiedLinkKeys.includes(link.key)" @change="setVerified(link.key,$event)"/>{{ t("Verified official destination") }}</label></div><Button size="sm" variant="outline" @click="snapshot.identity.links.push({key:newKey(),label:'',url:'https://',handle:null})">{{ t("Add destination") }}</Button>
   <h3 class="font-semibold">{{ t("Brand logos") }}</h3><div class="flex flex-wrap gap-4"><figure v-for="(logo,slot) in snapshot.logos" :key="slot"><img :src="api.image(org(),brandId,logo.sha256)" :alt="String(slot)" class="h-28 w-28 object-contain"/><figcaption>{{slot}}</figcaption></figure></div><div class="flex flex-wrap gap-3"><DeskSelect v-model="logoSlot" class="w-auto" :label="t('Logo slot')" :disabled="blocked || !workspace.canEdit.value" :options="[...(['master','on-light','on-dark','avatar','favicon','social']).map(slot => ({ value: slot, label: (t(slot)) }))]" /><DeskSelect v-model="libraryId" class="max-w-sm" :label="t('Uploaded logo')" :disabled="blocked || !workspace.canEdit.value" :options="[({ value: '' as const, label: (t('Choose image')) }), ...(workspace.media.value ?? []).map(media => ({ value: media.id, label: (media.fileName) }))]" /><Button :is-disabled="!libraryId" variant="outline" size="sm" @click="attach(true)">{{ t("Assign logo") }}</Button></div>
  </div>
  <div v-else-if="tab==='collections'" class="space-y-4"><Button variant="outline" @click="addCollection">{{ t("Add collection") }}</Button><article v-for="collection in snapshot.collections" :key="collection.id" class="workspace-card space-y-4 p-5"><p class="text-xs text-muted-foreground">{{collection.id}}</p><div class="grid gap-3 sm:grid-cols-3"><label v-for="language in ['uz','ru','en'] as const" :key="language">{{language.toUpperCase()}} {{ t("name") }}<input v-model="collection.names[language]" class="native-input mt-2"/></label></div><label class="block">{{ t("Description") }}<textarea v-model="collection.description" class="native-input mt-2"/></label><div class="flex flex-wrap gap-4"><label v-for="product in snapshot.products" :key="product.document.id" class="flex gap-2"><input v-model="collection.productIds" type="checkbox" :value="product.document.id"/>{{product.document.id}}</label></div><label class="flex gap-2"><input v-model="collection.isPublished" type="checkbox"/>{{ t("Include collection in the next release") }}</label></article></div>
  <div v-else-if="tab==='images'" class="grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="[hash,approval] in images" :key="hash" class="workspace-card space-y-3 p-4"><img :src="api.image(org(),brandId,hash)" :alt="t('Image awaiting provenance review')" class="h-56 w-full rounded-lg bg-muted object-contain"/><p class="truncate text-xs text-muted-foreground" :title="hash">SHA-256 {{hash}}</p><label class="block">{{ t("Image kind") }}<DeskSelect v-model="approval.kind" class="mt-2" :label="t('Image kind')" :disabled="blocked || !workspace.canEdit.value" :options="[({ value: 'unknown' as const, label: (t('unknown')) }), ({ value: 'photo' as const, label: (t('photo')) }), ({ value: 'visualization' as const, label: (t('visualization')) }), ({ value: 'archival' as const, label: (t('archival')) })]" /></label><label class="block">{{ t("Credit") }}<input v-model="approval.credit" class="native-input mt-2"/></label><label class="block">{{ t("Rights / permission") }}<input v-model="approval.rights" class="native-input mt-2"/></label><label class="block">{{ t("Source URL") }}<input v-model="approval.sourceUrl" class="native-input mt-2" type="url"/></label><label v-if="workspace.canApprove.value" class="flex gap-2"><input v-model="approval.approvedForPublication" type="checkbox" :disabled="approval.kind==='unknown'"/>{{ t("Approved for publication") }}</label></article><p v-if="!images.length" class="empty-state">{{ t("Attach images from Media to a product or logo slot.") }}</p></div>
  </fieldset>
  <section v-if="tab==='releases'" class="space-y-5"><div class="workspace-card space-y-4 p-6"><h2 class="text-xl font-semibold">{{ t("Publish a reviewed version") }}</h2><p class="text-sm text-muted-foreground">{{ t("Only active products with approved language copy and resolved questions appear. Draft prices, source notes, exact stock and unapproved images remain private.") }}</p><p v-if="dirty" class="text-sm">{{ t("Save your changes before publication.") }}</p><label class="block">{{ t("Release or withdrawal note") }}<textarea v-model="note" class="native-input mt-2" rows="2" maxlength="1000"/></label><Button v-if="workspace.canApprove.value" :is-disabled="blocked||dirty||!current||!note.trim()" @click="publish">{{ t("Publish catalogue") }}</Button></div>
   <article v-for="release in releases" :key="release.id" class="workspace-card flex flex-wrap items-center justify-between gap-4 p-5"><div><h3 class="font-semibold">{{ t("Release") }} {{release.revision}} · {{t(release.withdrawnAt?'Withdrawn':'Published')}}</h3><p class="text-sm">{{release.note}}</p><p class="text-xs text-muted-foreground">{{new Date(release.publishedAt).toLocaleString(uiLocale)}} {{ t("· Draft") }} {{release.sourceRevision}}</p><a v-if="!release.withdrawnAt" :href="`/api/public/v1/brands/${snapshot.slug}/catalogue?locale=en&release=${release.id}`" target="_blank" rel="noopener" class="text-sm underline">{{ t("View published catalogue data") }}</a></div><Button v-if="workspace.canApprove.value&&!release.withdrawnAt" variant="outline" size="sm" :is-disabled="blocked||dirty||!note.trim()" @click="withdraw(release)">{{ t("Withdraw with note") }}</Button></article>
  </section>
 </div>
</section>
</template>
